import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S06/S06E05.html","title":"S06E05 The One with Joey's Porsche","lang":"zh-CN","frontmatter":{"title":"S06E05 The One with Joey's Porsche","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":126},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":3}]},"readingTime":{"minutes":36.25,"words":10876},"filePathRelative":"语言/英语/Friends老友记/S06/S06E05.md"}`),l={name:`S06E05.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-with-joey-s-porsche" tabindex="-1"><a class="header-anchor" href="#the-one-with-joey-s-porsche"><span>The One with Joey&#39;s Porsche</span></a></h1><blockquote><p><em>乔伊的保时捷</em></p></blockquote><p>The One With Joey’s Porsche</p><blockquote><p>那辆乔伊的保时捷</p></blockquote><p><strong>Written by: Perry Rein &amp; Gigi McCreery</strong></p><blockquote><p>作者：Perry Rein&amp;Gigi McCreey</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, the gang is there except for Rachel and Ross, who both come storming in. Rachel is still going off about Ross’s secret marriage.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，除了瑞秋和罗斯，其他人都来了。瑞秋还在为罗斯的秘密婚姻发火。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S06/S06E05/001.mp3`}),c[1]||=i(),c[2]||=a(`strong`,null,`Rachel Green:`,-1),c[3]||=i(` I cannot believe that you didn’t tell me that we are still married!!`,-1),c[4]||=a(`blockquote`,null,[a(`p`,null,`我真不敢相信你没有告诉我我们还结婚！！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/002.mp3`}),c[5]||=i(),c[6]||=a(`strong`,null,`Ross Geller:`,-1),c[7]||=i(` Look I was going to tell you!`,-1),c[8]||=a(`blockquote`,null,[a(`p`,null,`听着，我正要告诉你！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/003.mp3`}),c[9]||=i(),c[10]||=a(`strong`,null,`Rachel Green:`,-1),c[11]||=i(` When?! After the birth of our first secret child?! (To All) Ross didn’t get the annulment; we are still married.`,-1),c[12]||=a(`blockquote`,null,[a(`p`,null,`什么时候？！在我们第一个秘密孩子出生后？！（对所有人）罗斯没有得到撤销；我们仍然结婚。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/004.mp3`}),c[13]||=i(),c[14]||=a(`strong`,null,`Chandler Bing:`,-1),c[15]||=i(` What?`,-1),c[16]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/005.mp3`}),c[17]||=i(),c[18]||=a(`strong`,null,`Monica Geller:`,-1),c[19]||=i(` You’re kidding!`,-1),c[20]||=a(`blockquote`,null,[a(`p`,null,`你在开玩笑！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/006.mp3`}),c[21]||=i(),c[22]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[23]||=i(` (overdoing it) Oh my God!!`,-1),c[24]||=a(`blockquote`,null,[a(`p`,null,`（做得太过火了）哦，我的天哪！！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/007.mp3`}),c[25]||=i(),c[26]||=a(`strong`,null,`Monica Geller:`,-1),c[27]||=i(` Ross!`,-1),c[28]||=a(`blockquote`,null,[a(`p`,null,`罗斯！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/008.mp3`}),c[29]||=i(),c[30]||=a(`strong`,null,`Ross Geller:`,-1),c[31]||=i(` Okay, maybe it wasn’t my best decision. But I just couldn’t face another failed marriage.`,-1),c[32]||=a(`blockquote`,null,[a(`p`,null,`好吧，也许这不是我最好的决定。但我无法面对另一场失败的婚姻。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/009.mp3`}),c[33]||=i(),c[34]||=a(`strong`,null,`Chandler Bing:`,-1),c[35]||=i(` Okay, let me just jump in and ask, at what point did you think this was a successful marriage?`,-1),c[36]||=a(`blockquote`,null,[a(`p`,null,`好吧，让我插进来问问，你认为这是一场成功的婚姻吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/010.mp3`}),c[37]||=i(),c[38]||=a(`strong`,null,`Ross Geller:`,-1),c[39]||=i(` Rach, come on, if you think about it, it’s actually kinda funny. (He laughs, and he laughs alone.) Okay, maybe it’s best not to think about it.`,-1),c[40]||=a(`blockquote`,null,[a(`p`,null,`瑞秋，来吧，如果你想一想，这其实有点好笑。（他笑了，他独自笑了。）好吧，也许最好不要去想它。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/011.mp3`}),c[41]||=i(),c[42]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[43]||=i(` Okay, this is inexcusable. I am shocked to my very core!`,-1),c[44]||=a(`blockquote`,null,[a(`p`,null,`好吧，这是不可原谅的。我感到非常震惊！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/012.mp3`}),c[45]||=i(),c[46]||=a(`strong`,null,`Ross Geller:`,-1),c[47]||=i(` Phoebe, I told her you already knew.`,-1),c[48]||=a(`blockquote`,null,[a(`p`,null,`菲比，我告诉她你已经知道了。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/013.mp3`}),c[49]||=i(),c[50]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[51]||=i(` Another lie. You have a sickness!`,-1),c[52]||=a(`blockquote`,null,[a(`p`,null,`又一个谎言。你生病了！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/014.mp3`}),c[53]||=t(` <strong>Chandler Bing:</strong> Ross, just for my own piece of mind, you’re not married to anymore of us are ya?<blockquote><p>罗斯，就为了我自己，你不再和我们结婚了，是吗？</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Central Perk, Joey and Monica are at the counter getting some more coffee.</em></p><blockquote><p>🎬 <em>中央公园，乔伊和莫妮卡在柜台边喝咖啡。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S06/S06E05/015.mp3`}),c[54]||=i(),c[55]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[56]||=i(` Oh! Hey, somebody left their keys. (Looks at them) Ooohh, to a Porsche! {Transcriber’s note: Oh come on! Who would leave the keys to their Porsche behind? If I had a Porsche, I’d have the keys surgically attached to my hand!} Hey Gunther, these yours?`,-1),c[57]||=a(`blockquote`,null,[a(`p`,null,`哦！嘿，有人把钥匙忘了。（看着他们）哦，对保时捷！{抄写者便条：哦，拜托！谁会把他们保时捷的钥匙留在身后？如果我有保时捷，我会把钥匙通过外科手术固定在我的手上！}嘿，冈瑟，这些是你的吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/016.mp3`}),c[58]||=i(),c[59]||=a(`strong`,null,`Gunther:`,-1),c[60]||=i(` Yeah, that’s what I drive. I make four bucks an hour, I saved up for 350 years!`,-1),c[61]||=a(`blockquote`,null,[a(`p`,null,`是的，我就是这样开车的。我一小时挣四美元，我攒了350年的钱！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/017.mp3`}),c[62]||=i(),c[63]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[64]||=i(` Na-uh! (To everyone there) Hey did anybody lose their keys?`,-1),c[65]||=a(`blockquote`,null,[a(`p`,null,`不，嗯！（对在场的每个人）嘿，有人丢了钥匙吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/018.mp3`}),c[66]||=i(),c[67]||=a(`strong`,null,`Monica Geller:`,-1),c[68]||=i(` Joey, why don’t you put them in the lost and found?`,-1),c[69]||=a(`blockquote`,null,[a(`p`,null,`乔伊，你为什么不把它们放在失物招领处呢？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/019.mp3`}),c[70]||=i(),c[71]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[72]||=i(` There’s a lost and found? (Gunther sets the box up on the table.) My shoe! (Grabs it out of the box.)`,-1),c[73]||=a(`blockquote`,null,[a(`p`,null,`有失物招领处吗？（冈瑟把盒子放在桌子上。）我的鞋！（从盒子里拿出来。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/020.mp3`}),c[74]||=i(),c[75]||=a(`strong`,null,`Chandler Bing:`,-1),c[76]||=i(` You left a shoe here?!`,-1),c[77]||=a(`blockquote`,null,[a(`p`,null,`你把鞋落在这里了？！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/021.mp3`}),c[78]||=i(),c[79]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[80]||=i(` Well, I didn’t realize until I got home. I wasn’t gonna walk all the way back down here with one shoe! Y’know what? I’m gonna go find that guy’s car and leave a note on the windshield. (Goes to do so.)`,-1),c[81]||=a(`blockquote`,null,[a(`p`,null,`嗯，我直到回家才意识到。我可不想一只鞋就走到这里来！你知道吗？我要去找那家伙的车，在挡风玻璃上留个条子。（去做吧。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/022.mp3`}),c[82]||=i(),c[83]||=a(`strong`,null,`Chandler Bing:`,-1),c[84]||=i(` Oh good, when he comes back for his keys, I’ll be sure to give him your shoe.`,-1),c[85]||=a(`blockquote`,null,[a(`p`,null,`哦，很好，当他回来取钥匙时，我一定会把你的鞋子给他。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/023.mp3`}),c[86]||=i(),c[87]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[88]||=i(` Great! Thanks. (Exits.)`,-1),c[89]||=a(`blockquote`,null,[a(`p`,null,`太好了！谢谢（退出。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/024.mp3`}),c[90]||=i(),c[91]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[92]||=i(` (coming in from the bathroom) Oh, good, good, you guys are here! Listen, how would like to spend tomorrow taking care of three incredibly cute little puppies?!`,-1),c[93]||=a(`blockquote`,null,[a(`p`,null,`（从浴室进来）哦，好，好，你们都来了！听着，你明天打算怎么照顾三只非常可爱的小狗？！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/025.mp3`}),c[94]||=i(),c[95]||=a(`strong`,null,`Monica Geller:`,-1),c[96]||=i(` Oh my God, what a fun day! That sounds great!`,-1),c[97]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天，多有趣的一天啊！听起来很棒！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/026.mp3`}),c[98]||=i(),c[99]||=a(`strong`,null,`Chandler Bing:`,-1),c[100]||=i(` (not enthused) Yeah, all right.`,-1),c[101]||=a(`blockquote`,null,[a(`p`,null,`（没有热情）是的，好吧。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/027.mp3`}),c[102]||=i(),c[103]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[104]||=i(` Okay, well I’ll bring them by tomorrow morning. Okay, and uh, by the way, they’re not actually puppies, they’re Frank and Alice’s triplets. Okay, see ya! (Exits.)`,-1),c[105]||=a(`blockquote`,null,[a(`p`,null,`好吧，明天早上我会把它们带来。好吧，顺便说一句，它们不是小狗，它们是弗兰克和爱丽丝的三胞胎。好的，再见！（退出。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/028.mp3`}),c[106]||=i(),c[107]||=a(`strong`,null,`Chandler Bing:`,-1),c[108]||=i(` Whoa-whoa-whoa! What?`,-1),c[109]||=a(`blockquote`,null,[a(`p`,null,`哇，哇，哇！什么？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/029.mp3`}),c[110]||=i(),c[111]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[112]||=i(` (stops) Please! Please! Please! Please! Oh please! Please! Please! Frank and Alice asked me to baby sit the triplets and I’m nervous ‘cause I’ve never done that before by myself!`,-1),c[113]||=a(`blockquote`,null,[a(`p`,null,`（停下来）求你了！请请请哦，求你了！请请弗兰克和爱丽丝让我照看这对三胞胎，我很紧张，因为我从来没有独自做过！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/030.mp3`}),c[114]||=i(),c[115]||=a(`strong`,null,`Monica Geller:`,-1),c[116]||=i(` Don’t worry about it Phoebe, we’ll absolutely do it.`,-1),c[117]||=a(`blockquote`,null,[a(`p`,null,`别担心，菲比，我们绝对会做的。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/031.mp3`}),c[118]||=i(),c[119]||=a(`strong`,null,`Chandler Bing:`,-1),c[120]||=i(` Yeah, I’m gonna pass. ‘Cause I was kinda iffy when it was puppies.`,-1),c[121]||=a(`blockquote`,null,[a(`p`,null,`是的，我会通过的因为当我是小狗的时候我有点怀疑。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/032.mp3`}),c[122]||=t(` <strong>Monica Geller:</strong> Come on Chandler, come on! It’ll give us great practice for when—(realizes what she’s about to say and changes)—people with babies come to visit.<blockquote><p>快点，钱德勒，快点！当（意识到她将要说的话并改变）有婴儿的人来拜访时，这会给我们很大的练习。</p></blockquote><hr><p>🎬 <em>The street down the block from Central Perk, Joey has found the Porsche and is writing the note.</em></p><blockquote><p>🎬 <em>从中央公园一个街区下来的那条街上，乔伊找到了那辆保时捷，正在写便条。</em></p></blockquote><p>Guy #1: Nice car!</p><blockquote><p>好车！</p></blockquote>`,9),r(p,{src:`/audio/friends/S06/S06E05/033.mp3`}),c[123]||=i(),c[124]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[125]||=i(` Yeah, it’s not mine.`,-1),c[126]||=a(`blockquote`,null,[a(`p`,null,`是的，不是我的。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/034.mp3`}),c[127]||=i(),c[128]||=a(`strong`,null,`Woman:`,-1),c[129]||=i(` (walking up) I love your car.`,-1),c[130]||=a(`blockquote`,null,[a(`p`,null,`（走上前）我喜欢你的车。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/035.mp3`}),c[131]||=i(),c[132]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[133]||=i(` Yeah, it’s (looks up and sees the woman) mine.`,-1),c[134]||=a(`blockquote`,null,[a(`p`,null,`是的，它是我的。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/036.mp3`}),c[135]||=i(),c[136]||=a(`strong`,null,`Woman:`,-1),c[137]||=i(` I bet it’s fast.`,-1),c[138]||=a(`blockquote`,null,[a(`p`,null,`我打赌它很快。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/037.mp3`}),c[139]||=i(),c[140]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[141]||=i(` Me too! Yeah. And comfortable. Do uh, do you like leather seats?`,-1),c[142]||=a(`blockquote`,null,[a(`p`,null,`我也是！是 啊而且很舒服。你喜欢真皮座椅吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/038.mp3`}),c[143]||=i(),c[144]||=a(`strong`,null,`Woman:`,-1),c[145]||=i(` Yeah!`,-1),c[146]||=a(`blockquote`,null,[a(`p`,null,`是啊！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/039.mp3`}),c[147]||=i(),c[148]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[149]||=i(` (checks in the window to make sure it has them) It’s got ‘em!`,-1),c[150]||=a(`blockquote`,null,[a(`p`,null,`（在窗户里检查确认有没有）有了！`)],-1),c[151]||=a(`hr`,null,null,-1),c[152]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Phoebe and Rachel are having tea.`)],-1),c[153]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，菲比和瑞秋正在喝茶。`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/040.mp3`}),c[154]||=i(),c[155]||=a(`strong`,null,`Rachel Green:`,-1),c[156]||=i(` So, I still have boxes here. I still have boxes at Ross’s, and I have nowhere to live! Wow. I could so easily freak out right now.`,-1),c[157]||=a(`blockquote`,null,[a(`p`,null,`所以，我这里还有盒子。罗斯家还有箱子，我没有地方住了！哇！我现在很容易就发疯了。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/041.mp3`}),c[158]||=i(),c[159]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[160]||=i(` What about me? I just found out that Denise is leaving town for a while, I don’t have a roommate.`,-1),c[161]||=a(`blockquote`,null,[a(`p`,null,`那我呢？我刚发现丹尼斯要离开一段时间，我没有室友。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/042.mp3`}),c[162]||=i(),c[163]||=a(`strong`,null,`Rachel Green:`,-1),c[164]||=i(` Well, maybe-maybe I could be your roommate Pheebs.`,-1),c[165]||=a(`blockquote`,null,[a(`p`,null,`嗯，也许我可以成为你的室友菲比。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/043.mp3`}),c[166]||=i(),c[167]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[168]||=i(` Maybe you could be my roommate!`,-1),c[169]||=a(`blockquote`,null,[a(`p`,null,`也许你可以成为我的室友！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/044.mp3`}),c[170]||=i(),c[171]||=a(`strong`,null,`Rachel Green:`,-1),c[172]||=i(` Well there’s an idea!!`,-1),c[173]||=a(`blockquote`,null,[a(`p`,null,`有个主意！！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/045.mp3`}),c[174]||=i(),c[175]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[176]||=i(` Yeah!`,-1),c[177]||=a(`blockquote`,null,[a(`p`,null,`是啊！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/046.mp3`}),c[178]||=i(),c[179]||=a(`strong`,null,`Rachel Green:`,-1),c[180]||=i(` That would be great! Wait, how long is Denise gone for?`,-1),c[181]||=a(`blockquote`,null,[a(`p`,null,`那太好了！等等，丹尼斯离开多久了？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/047.mp3`}),c[182]||=i(),c[183]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[184]||=i(` Umm, she said she’d be back December 26th.`,-1),c[185]||=a(`blockquote`,null,[a(`p`,null,`嗯，她说她会在12月26日回来。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/048.mp3`}),c[186]||=i(),c[187]||=a(`strong`,null,`Rachel Green:`,-1),c[188]||=i(` December 26th, huh maybe she’s Santa Clause.`,-1),c[189]||=a(`blockquote`,null,[a(`p`,null,`12月26日，也许她是圣诞老人。`)],-1),c[190]||=a(`p`,null,[a(`em`,null,`(Phoebe laughs, then stops to think about it. Ross enters.)`)],-1),c[191]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（菲比笑了，然后停下来想了想。罗斯进来了。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/049.mp3`}),c[192]||=i(),c[193]||=a(`strong`,null,`Rachel Green:`,-1),c[194]||=i(` (deadpan) Oh look who it is, my husband. The apple of my eye.`,-1),c[195]||=a(`blockquote`,null,[a(`p`,null,`（面无表情）哦，看看是谁，我丈夫。我的掌上明珠。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/050.mp3`}),c[196]||=i(),c[197]||=a(`strong`,null,`Ross Geller:`,-1),c[198]||=i(` Okay, I got us a court date for tomorrow at 2:00 and I picked up all the forms. I’ll take care of everything.`,-1),c[199]||=a(`blockquote`,null,[a(`p`,null,`好吧，我给我们定了明天2:00的开庭日期，我把所有的表格都拿了出来。我会处理好一切的。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/051.mp3`}),c[200]||=i(),c[201]||=a(`strong`,null,`Rachel Green:`,-1),c[202]||=i(` Well sure, if you say you’re gonna take care of everything I have no reason to doubt you. Give me those forms! (Grabs them from him.) All right, now I’m gonna do this my way and I don’t want to hear a peep out of you!`,-1),c[203]||=a(`blockquote`,null,[a(`p`,null,`当然，如果你说你会处理好一切，我没有理由怀疑你。把那些表格给我！（从他手里接过）好吧，现在我要按我自己的方式做，我不想听到你的偷窥声！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/052.mp3`}),c[204]||=i(),c[205]||=a(`strong`,null,`Ross Geller:`,-1),c[206]||=i(` Okay Rach, but…`,-1),c[207]||=a(`blockquote`,null,[a(`p`,null,`好吧，瑞秋，但是…`)],-1),r(p,{src:`/audio/friends/S06/S06E05/053.mp3`}),c[208]||=i(),c[209]||=a(`strong`,null,`Rachel Green:`,-1),c[210]||=i(` Op! You’re peeping!`,-1),c[211]||=a(`blockquote`,null,[a(`p`,null,`啊！你在偷看！`)],-1),c[212]||=a(`p`,null,[a(`em`,null,`(Ross grunts something and hands her the pen he was trying to hand her.)`)],-1),c[213]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯咕哝了一声，把他想递给她的笔递给了她。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/054.mp3`}),c[214]||=i(),c[215]||=a(`strong`,null,`Rachel Green:`,-1),c[216]||=i(` Ross! Y’know what, I just got—why? Why did you do this?!`,-1),c[217]||=a(`blockquote`,null,[a(`p`,null,`罗斯！你知道吗，我刚知道为什么？你为什么这么做？！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/055.mp3`}),c[218]||=i(),c[219]||=a(`strong`,null,`Ross Geller:`,-1),c[220]||=i(` Look I told you…`,-1),c[221]||=a(`blockquote`,null,[a(`p`,null,`听着，我告诉过你…`)],-1),r(p,{src:`/audio/friends/S06/S06E05/056.mp3`}),c[222]||=i(),c[223]||=a(`strong`,null,`Rachel Green:`,-1),c[224]||=i(` I don’t wanna hear "Three failed marriages!"`,-1),c[225]||=a(`blockquote`,null,[a(`p`,null,`我不想听“三次失败的婚姻！”`)],-1),r(p,{src:`/audio/friends/S06/S06E05/057.mp3`}),c[226]||=i(),c[227]||=a(`strong`,null,`Ross Geller:`,-1),c[228]||=i(` Look, if you’d had two failed marriages, you’d understand!`,-1),c[229]||=a(`blockquote`,null,[a(`p`,null,`听着，如果你有过两次失败的婚姻，你会明白的！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/058.mp3`}),c[230]||=i(),c[231]||=a(`strong`,null,`Rachel Green:`,-1),c[232]||=i(` Well, y’know what? Thanks to you I’m half way there! Ugh! Oh! I am so mad! Ross, I don’t think I have ever been this angry!`,-1),c[233]||=a(`blockquote`,null,[a(`p`,null,`嗯，你知道吗？多亏了你，我才成功了一半！啊！哦我真是疯了！罗斯，我想我从来没有这么生气过！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/059.mp3`}),c[234]||=i(),c[235]||=a(`strong`,null,`Ross Geller:`,-1),c[236]||=i(` What about the time I said we were on a break?`,-1),c[237]||=a(`blockquote`,null,[a(`p`,null,`那我说我们休息的时候呢？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/060.mp3`}),c[238]||=i(),c[239]||=a(`strong`,null,`Rachel Green:`,-1),c[240]||=i(` Ugh! (Stares at him.)`,-1),c[241]||=a(`blockquote`,null,[a(`p`,null,`啊！（盯着他看。）`)],-1),c[242]||=a(`hr`,null,null,-1),c[243]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, the next day, Chandler, Monica, and Phoebe are baby-sitting the triplets. They each have one baby.`)],-1),c[244]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，第二天，钱德勒、莫妮卡和菲比照看这对三胞胎。他们各自有一个孩子。`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/061.mp3`}),c[245]||=i(),c[246]||=a(`strong`,null,`Monica Geller:`,-1),c[247]||=i(` Pheebs, how’s it going?`,-1),c[248]||=a(`blockquote`,null,[a(`p`,null,`菲比，最近怎么样？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/062.mp3`}),c[249]||=i(),c[250]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[251]||=i(` (rapidly) I’m doing okay. I think it’s going well. Do you think they’re having fun? Am I talking to fast?`,-1),c[252]||=a(`blockquote`,null,[a(`p`,null,`（迅速地）我很好。我认为进展顺利。你觉得他们玩得开心吗？我在跟fast说话吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/063.mp3`}),c[253]||=i(),c[254]||=a(`strong`,null,`Monica Geller:`,-1),c[255]||=i(` Nope, sound like me. Pheebs, it’s going great. Look at Chandler with little baby girl Chandler.`,-1),c[256]||=a(`blockquote`,null,[a(`p`,null,`不，听起来像我。菲比，一切都很顺利。看看钱德勒和小女婴钱德勒。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/064.mp3`}),c[257]||=i(),c[258]||=a(`strong`,null,`Chandler Bing:`,-1),c[259]||=i(` Little baby girl Chandler, where I have heard that before? Oh right, Coach Ruben. (Tries to get her to drink a little more from the bottle when he suddenly smells something. It’s times like these I’m glad Smell-O-Vision hasn’t been invented.) Do you know what Pheebs? When you’re done over there, we kinda have a situation over here too. (Phoebe is changing hers.)`,-1),c[260]||=a(`blockquote`,null,[a(`p`,null,`小女婴钱德勒，我以前在哪里听说过？哦，对了，鲁本教练。（当他突然闻到什么东西时，试图让她从瓶子里再喝一点。现在是这样的时候，我很高兴嗅觉视觉还没有发明。）你知道菲比是什么吗？当你在那里完成后，我们这里也有一种情况。（菲比正在换衣服。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/065.mp3`}),c[261]||=i(),c[262]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[263]||=i(` Na-uh, no, we are all responsible for our own babies.`,-1),c[264]||=a(`blockquote`,null,[a(`p`,null,`不，不，我们都要为自己的孩子负责。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/066.mp3`}),c[265]||=i(),c[266]||=a(`strong`,null,`Chandler Bing:`,-1),c[267]||=i(` See that’s where I think that you’re wrong. We’ve been playing these babies man for man; we should really be playing a zone defense.`,-1),c[268]||=a(`blockquote`,null,[a(`p`,null,`看，这就是我认为你错的地方。我们一直在为这些婴儿玩一对一的游戏；我们真的应该打区域防守。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/067.mp3`}),c[269]||=i(),c[270]||=a(`strong`,null,`Monica Geller:`,-1),c[271]||=i(` What do you mean?`,-1),c[272]||=a(`blockquote`,null,[a(`p`,null,`你什么意思？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/068.mp3`}),c[273]||=i(),c[274]||=a(`strong`,null,`Chandler Bing:`,-1),c[275]||=i(` I just think that things would go a lot smoother if we each have our own zone. Phoebe, you can be in charge of wiping. And y’know Mon, you can be in charge of diapering and I can be in charge of looking how cute they are when they put their hands around… (He degrades into baby talk, but he means when they grab his finger.)`,-1),c[276]||=a(`blockquote`,null,[a(`p`,null,`我只是觉得如果我们每个人都有自己的区域，事情会顺利得多。菲比，你可以负责擦拭。你知道，拜托，你可以负责尿布，我可以负责看着他们把手放在周围时有多可爱…（他退化成婴儿说话，但他的意思是当他们抓住他的手指时。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/069.mp3`}),c[277]||=i(),c[278]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[279]||=i(` That sounds really great, but maybe you should be in charge of wiping.`,-1),c[280]||=a(`blockquote`,null,[a(`p`,null,`听起来真的很棒，但也许你应该负责擦拭。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/070.mp3`}),c[281]||=i(),c[282]||=a(`strong`,null,`Chandler Bing:`,-1),c[283]||=i(` Okay, I’m a rookie. I should not be in the end zone.`,-1),c[284]||=a(`blockquote`,null,[a(`p`,null,`好吧，我是新手。我不应该在终点区。`)],-1),c[285]||=a(`p`,null,[i(`⏱ `),a(`em`,null,`Time lapse, they have set up a little assembly line for diaper changes. Phoebe wipes, Chandler adds the powder, begrudgingly, and Monica puts the diaper on.`)],-1),c[286]||=a(`blockquote`,null,[a(`p`,null,[i(`⏱ `),a(`em`,null,`随着时间的推移，他们已经建立了一条换尿布的小流水线。菲比擦拭，钱德勒不情愿地加了粉，莫妮卡把尿布穿上。`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/071.mp3`}),c[287]||=i(),c[288]||=a(`strong`,null,`Monica Geller:`,-1),c[289]||=i(` This is so great! This is exactly how we set the plates at the restaurant.`,-1),c[290]||=a(`blockquote`,null,[a(`p`,null,`这太棒了！这正是我们在餐厅摆盘子的方式。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/072.mp3`}),c[291]||=i(),c[292]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[293]||=i(` Yeah? (Checking the final diaper) Well this is not what I ordered.`,-1),c[294]||=a(`blockquote`,null,[a(`p`,null,`是吗？（检查最后的尿布）这不是我点的。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/073.mp3`}),c[295]||=i(),c[296]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[297]||=i(` (entering) Hey guys!`,-1),c[298]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿，伙计们！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/074.mp3`}),c[299]||=i(),c[300]||=a(`strong`,null,`Chandler Bing:`,-1),c[301]||=i(` Hey!`,-1),c[302]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/075.mp3`}),c[303]||=i(),c[304]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[305]||=i(` Hey!`,-1),c[306]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/076.mp3`}),c[307]||=i(),c[308]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[309]||=i(` Hey babies! Oh, I’m having the best morning. That uh, that Porsche I’ve got the keys too, still there!`,-1),c[310]||=a(`blockquote`,null,[a(`p`,null,`嘿，宝贝们！哦，我今天早上过得很愉快。那辆保时捷我也有钥匙，还在那儿！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/077.mp3`}),c[311]||=i(),c[312]||=a(`strong`,null,`Chandler Bing:`,-1),c[313]||=i(` Shocking! Since you still have the keys.`,-1),c[314]||=a(`blockquote`,null,[a(`p`,null,`令人震惊！既然你还有钥匙。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/078.mp3`}),c[315]||=i(),c[316]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[317]||=i(` You should see the treatment I get when I’m with that car! People are friendly; they-they wanna talk, and not just about the car! One guy gave me advice about my equity investments.`,-1),c[318]||=a(`blockquote`,null,[a(`p`,null,`你应该看看我和那辆车在一起时受到的待遇！人民友好,；他们想谈谈，不仅仅是关于汽车！一个人给了我关于股票投资的建议。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/079.mp3`}),c[319]||=i(),c[320]||=a(`strong`,null,`Chandler Bing:`,-1),c[321]||=i(` What equity investments?`,-1),c[322]||=a(`blockquote`,null,[a(`p`,null,`什么股票投资？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/080.mp3`}),c[323]||=i(),c[324]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[325]||=i(` The ones that got me the Porsche! Will you keep up! (Chandler wipes his forehead with a baby wipe, that might have been used. He drops it disgustedly.) But I figured, if-if people keep seeing me just standing there, they’re gonna start to think that I don’t own it. So I figured I’ll wash it. Right? Monica, you got a bucket and some soap I can borrow?`,-1),c[326]||=a(`blockquote`,null,[a(`p`,null,`就是那些给我买保时捷的！你能跟上吗！（钱德勒用婴儿湿巾擦额头，那可能是用过的。他厌恶地把它掉了下来。）但我想，如果人们一直看到我站在那里，他们会开始认为我不拥有它。所以我想我会洗的。对吗？莫妮卡，你有水桶和肥皂我可以借吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/081.mp3`}),c[327]||=i(),c[328]||=a(`strong`,null,`Monica Geller:`,-1),c[329]||=i(` Oh yeah, I got soap and sponges and rags and Carnuba wax and polishing compound.`,-1),c[330]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，我有肥皂、海绵、抹布、肉豆蔻蜡和抛光剂。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/082.mp3`}),c[331]||=i(),c[332]||=a(`strong`,null,`Chandler Bing:`,-1),c[333]||=i(` You don’t even have a car!`,-1),c[334]||=a(`blockquote`,null,[a(`p`,null,`你连车都没有！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/083.mp3`}),c[335]||=i(),c[336]||=a(`strong`,null,`Monica Geller:`,-1),c[337]||=i(` I know. But umm, one time there was this really dirty car in front of the building, so I washed it.`,-1),c[338]||=a(`blockquote`,null,[a(`p`,null,`我知道。但是，有一次，大楼前面有一辆非常脏的车，所以我把它洗了。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/084.mp3`}),c[339]||=i(),c[340]||=a(`strong`,null,`Chandler Bing:`,-1),c[341]||=i(` And?`,-1),c[342]||=a(`blockquote`,null,[a(`p`,null,`然后呢？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/085.mp3`}),c[343]||=i(),c[344]||=a(`strong`,null,`Monica Geller:`,-1),c[345]||=i(` And six others.`,-1),c[346]||=a(`blockquote`,null,[a(`p`,null,`还有六个人。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/086.mp3`}),c[347]||=i(),c[348]||=a(`strong`,null,`Chandler Bing:`,-1),c[349]||=i(` There you are.`,-1),c[350]||=a(`blockquote`,null,[a(`p`,null,`给你。`)],-1),c[351]||=a(`hr`,null,null,-1),c[352]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The Porsche, Joey is finishing up washing the car and is talking to a guy about the car.`)],-1),c[353]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`保时捷，乔伊正在洗车，正在和一个男人谈论这辆车。`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/087.mp3`}),c[354]||=i(),c[355]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[356]||=i(` Yeah, she tops out at 130.`,-1),c[357]||=a(`blockquote`,null,[a(`p`,null,`是的，她最多130岁。`)],-1),c[358]||=a(`p`,null,`Guy #2: Wow!`,-1),c[359]||=a(`blockquote`,null,[a(`p`,null,`盖伊2：哇！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/088.mp3`}),c[360]||=i(),c[361]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[362]||=i(` And that’s just in the city. I get her up to 160 when I take her upstate.`,-1),c[363]||=a(`blockquote`,null,[a(`p`,null,`那只是在城市里。当我带她去北部的时候，她可以达到160。`)],-1),c[364]||=a(`p`,null,`Guy #2: Really! You got a place upstate?`,-1),c[365]||=a(`blockquote`,null,[a(`p`,null,`真的！你在北部有地方吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/089.mp3`}),c[366]||=i(),c[367]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[368]||=i(` Sure!`,-1),c[369]||=a(`blockquote`,null,[a(`p`,null,`当然！`)],-1),c[370]||=a(`p`,null,`Guy #2: Well, I’ll see you later.`,-1),c[371]||=a(`blockquote`,null,[a(`p`,null,`盖伊2：好吧，待会儿见。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/090.mp3`}),c[372]||=i(),c[373]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[374]||=i(` Okay, take it easy.`,-1),c[375]||=a(`blockquote`,null,[a(`p`,null,`好的，别紧张。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/091.mp3`}),c[376]||=i(),c[377]||=a(`strong`,null,`The Porsche Owner:`,-1),c[378]||=i(` Hey! That’s my car.`,-1),c[379]||=a(`blockquote`,null,[a(`p`,null,`嘿！那是我的车。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/092.mp3`}),c[380]||=i(),c[381]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[382]||=i(` Really? Oh uh, oh just give me five more minutes with it.`,-1),c[383]||=a(`blockquote`,null,[a(`p`,null,`真的吗？哦，哦，再给我五分钟。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/093.mp3`}),c[384]||=i(),c[385]||=a(`strong`,null,`The Porsche Owner:`,-1),c[386]||=i(` What-what are you doing?`,-1),c[387]||=a(`blockquote`,null,[a(`p`,null,`你在干什么？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/094.mp3`}),c[388]||=i(),c[389]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[390]||=i(` Oh I-I uh, found the keys and now I’m just polishing her up.`,-1),c[391]||=a(`blockquote`,null,[a(`p`,null,`哦，我找到钥匙了，现在我只是在给她擦屁股。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/095.mp3`}),c[392]||=i(),c[393]||=a(`strong`,null,`The Porsche Owner:`,-1),c[394]||=i(` But it’s my car!`,-1),c[395]||=a(`blockquote`,null,[a(`p`,null,`但那是我的车！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/096.mp3`}),c[396]||=i(),c[397]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[398]||=i(` Yeah, but it’s my wax.`,-1),c[399]||=a(`blockquote`,null,[a(`p`,null,`是的，但这是我的蜡。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/097.mp3`}),c[400]||=i(),c[401]||=a(`strong`,null,`The Porsche Owner:`,-1),c[402]||=i(` Listen, I-I-I don’t come to this city much so I don’t know if you’re crazy or this is some kind of street theater, but could I have my keys.`,-1),c[403]||=a(`blockquote`,null,[a(`p`,null,`听着，我不常来这个城市，所以我不知道你是不是疯了，或者这是什么街头剧场，但我可以要我的钥匙吗。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/098.mp3`}),c[404]||=i(),c[405]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[406]||=i(` Sure. Here. (He hands them over.) I’ll uh, save your parking spot.`,-1),c[407]||=a(`blockquote`,null,[a(`p`,null,`当然。在这里（他把它们递过来）我会呃，保留你的停车位。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/099.mp3`}),c[408]||=i(),c[409]||=a(`strong`,null,`The Porsche Owner:`,-1),c[410]||=i(` I’m not coming back.`,-1),c[411]||=a(`blockquote`,null,[a(`p`,null,`我不会回来了。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/100.mp3`}),c[412]||=i(),c[413]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[414]||=i(` Why not?`,-1),c[415]||=a(`blockquote`,null,[a(`p`,null,`为什么不呢？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/101.mp3`}),c[416]||=i(),c[417]||=a(`strong`,null,`The Porsche Owner:`,-1),c[418]||=i(` I live upstate.`,-1),c[419]||=a(`blockquote`,null,[a(`p`,null,`我住在北部。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/102.mp3`}),c[420]||=t(` <strong>Joey Tribbiani:</strong> Yeah, so did I.<blockquote><p>是的，我也是。</p></blockquote><p><em>(The guy gets in and drives off.)</em></p><blockquote><p><em>（那家伙上车开车走了。）</em></p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, the triplets are all in their crib as Monica and Phoebe watch them.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，当莫妮卡和菲比看着他们时，三胞胎都在婴儿床上。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S06/S06E05/103.mp3`}),c[421]||=i(),c[422]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[423]||=i(` I don’t know why I was so nervous about this. And I don’t know why Frank and Alice are always complaining. This is so easy.`,-1),c[424]||=a(`blockquote`,null,[a(`p`,null,`我不知道为什么我对这件事这么紧张。我不知道为什么弗兰克和爱丽丝总是抱怨。这太容易了。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/104.mp3`}),c[425]||=i(),c[426]||=a(`strong`,null,`Monica Geller:`,-1),c[427]||=i(` Yeah, two hours, a lifetime that’s the same.`,-1),c[428]||=a(`blockquote`,null,[a(`p`,null,`是的，两个小时，一辈子都一样。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/105.mp3`}),c[429]||=i(),c[430]||=a(`strong`,null,`Chandler Bing:`,-1),c[431]||=i(` (entering) Check it out! Check it out! When the babies wake up, they can meet Krog! (He holds up this Xena-like warrior action figure.)`,-1),c[432]||=a(`blockquote`,null,[a(`p`,null,`（进来）看看！过来看！当孩子们醒来时，他们可以见到克罗格！（他举着这个像塞纳一样的战士动作图。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/106.mp3`}),c[433]||=i(),c[434]||=a(`strong`,null,`Monica Geller:`,-1),c[435]||=i(` Chandler, what are you doing? That thing can put someone’s eye out!`,-1),c[436]||=a(`blockquote`,null,[a(`p`,null,`钱德勒，你在干什么？那东西会把人的眼睛弄瞎的！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/107.mp3`}),c[437]||=i(),c[438]||=a(`strong`,null,`Chandler Bing:`,-1),c[439]||=i(` He can do more than that! He can destroy the universe!`,-1),c[440]||=a(`blockquote`,null,[a(`p`,null,`他能做的不止这些！他可以毁灭宇宙！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/108.mp3`}),c[441]||=i(),c[442]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[443]||=i(` No Chandler, they can swallow one of those little parts! And also, look at his smooth area, that’s just gonna mess them up.`,-1),c[444]||=a(`blockquote`,null,[a(`p`,null,`不，钱德勒，他们可以吞下一个小零件！还有，看看他平滑的区域，那会把他们搞砸的。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/109.mp3`}),c[445]||=i(),c[446]||=a(`strong`,null,`Chandler Bing:`,-1),c[447]||=i(` They’re not gonna swallow anything, you guys are being way over protective. When I was a kid, my mom used to just throw me into a pile of broken glass!`,-1),c[448]||=a(`blockquote`,null,[a(`p`,null,`他们不会吞下任何东西的，你们这些家伙太过分了。当我还是个孩子的时候，我妈妈总是把我扔进一堆碎玻璃里！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/110.mp3`}),c[449]||=i(),c[450]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[451]||=i(` What?!`,-1),c[452]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/111.mp3`}),c[453]||=i(),c[454]||=a(`strong`,null,`Chandler Bing:`,-1),c[455]||=i(` Glass, sand, whatever. (Walks out as Monica and Phoebe turn to check on the babies again.)`,-1),c[456]||=a(`blockquote`,null,[a(`p`,null,`玻璃，沙子，随便什么。（莫妮卡和菲比再次转身检查婴儿时走出去。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/112.mp3`}),c[457]||=i(),c[458]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[459]||=i(` Oh, look at little Leslie stretching in her sleep.`,-1),c[460]||=a(`blockquote`,null,[a(`p`,null,`哦，看小莱斯利在睡梦中伸展身体。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/113.mp3`}),c[461]||=i(),c[462]||=a(`strong`,null,`Monica Geller:`,-1),c[463]||=i(` Oh it’s so cute. I wonder what age it is when you stop being able to put both legs over your head.`,-1),c[464]||=a(`blockquote`,null,[a(`p`,null,`哦，太可爱了。我想知道你什么时候不能把双腿放在头上了。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/114.mp3`}),c[465]||=i(),c[466]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[467]||=i(` Oh, I can still do that.`,-1),c[468]||=a(`blockquote`,null,[a(`p`,null,`哦，我还是可以的。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/115.mp3`}),c[469]||=i(),c[470]||=a(`strong`,null,`Monica Geller:`,-1),c[471]||=i(` How are you still single?!`,-1),c[472]||=a(`blockquote`,null,[a(`p`,null,`你怎么还单身？！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/116.mp3`}),c[473]||=i(),c[474]||=a(`strong`,null,`Chandler Bing:`,-1),c[475]||=i(` (entering) All right. (Clears throat) I thought about it and maybe you’re right. Maybe Krog is not a safe toy.`,-1),c[476]||=a(`blockquote`,null,[a(`p`,null,`（进来）好的。（清了清嗓子）我想了想，也许你是对的。也许克罗格不是一个安全的玩具。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/117.mp3`}),c[477]||=i(),c[478]||=a(`strong`,null,`Monica Geller:`,-1),c[479]||=i(` Good. What made you change your mind?`,-1),c[480]||=a(`blockquote`,null,[a(`p`,null,`好的。是什么让你改变了主意？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/118.mp3`}),c[481]||=i(),c[482]||=a(`strong`,null,`Chandler Bing:`,-1),c[483]||=i(` I swallowed the sonic blaster gun.`,-1),c[484]||=a(`blockquote`,null,[a(`p`,null,`我吞下了声爆枪。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/119.mp3`}),c[485]||=i(),c[486]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[487]||=i(` How did that happen?!!`,-1),c[488]||=a(`blockquote`,null,[a(`p`,null,`那是怎么发生的？！！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/120.mp3`}),c[489]||=i(),c[490]||=a(`strong`,null,`Chandler Bing:`,-1),c[491]||=i(` Well, I was trying to prove that I was right. Y’know? And it turns out I was wrong. And now it’s lodged in my throat. (Mimics a cat trying to cough up a hairball.) (He does it again.)`,-1),c[492]||=a(`blockquote`,null,[a(`p`,null,`嗯，我想证明我是对的。你知道吗？结果证明我错了。现在它卡在我的喉咙里了。（模仿一只猫试图吐出一个毛球。）（他又吐了一次。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/121.mp3`}),c[493]||=i(),c[494]||=a(`strong`,null,`Monica Geller:`,-1),c[495]||=i(` Damnit! Y’know this whole time we were concentrating on watching the babies and, and no one was watching Chandler! (He does it again.)`,-1),c[496]||=a(`blockquote`,null,[a(`p`,null,`该死！你知道吗，这段时间我们一直专注于看孩子们，没有人在看钱德勒！（他又做了一次。）`)],-1),c[497]||=a(`hr`,null,null,-1),c[498]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`A judge’s chambers, Rachel and Ross are filing their annulment papers.`)],-1),c[499]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`法官办公室，瑞秋和罗斯正在提交他们的撤销文件。`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/122.mp3`}),c[500]||=i(),c[501]||=a(`strong`,null,`Judge:`,-1),c[502]||=i(` Okay you two are asking the court for an annulment?`,-1),c[503]||=a(`blockquote`,null,[a(`p`,null,`好吧，你们两个要向法庭申请撤销吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/123.mp3`}),c[504]||=i(),c[505]||=a(`strong`,null,`Rachel Green:`,-1),c[506]||=i(` Yes your honor, and here are, are forms, all filled out.`,-1),c[507]||=a(`blockquote`,null,[a(`p`,null,`是的，法官大人，这是表格，都填好了。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/124.mp3`}),c[508]||=i(),c[509]||=a(`strong`,null,`Judge:`,-1),c[510]||=i(` So based on your petition you are seeking an annulment on the grounds that Mr. Geller is mentally unstable.`,-1),c[511]||=a(`blockquote`,null,[a(`p`,null,`那么根据你的请愿书，你以盖勒先生精神不稳定为理由，要求撤销合同。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/125.mp3`}),c[512]||=i(),c[513]||=a(`strong`,null,`Ross Geller:`,-1),c[514]||=i(` Fine, I’m mentally unstable.`,-1),c[515]||=a(`blockquote`,null,[a(`p`,null,`好吧，我精神不稳定。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/126.mp3`}),c[516]||=i(),c[517]||=a(`strong`,null,`Judge:`,-1),c[518]||=i(` And based on the fact that Mr. Geller is intravenous drug user.`,-1),c[519]||=a(`blockquote`,null,[a(`p`,null,`根据盖勒先生是静脉注射毒品使用者这一事实。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/127.mp3`}),c[520]||=i(),c[521]||=a(`strong`,null,`Ross Geller:`,-1),c[522]||=i(` What?!`,-1),c[523]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/128.mp3`}),c[524]||=i(),c[525]||=a(`strong`,null,`Rachel Green:`,-1),c[526]||=i(` Uh yes, heroin and crack.`,-1),c[527]||=a(`blockquote`,null,[a(`p`,null,`嗯，是的，海洛因和可卡因。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/129.mp3`}),c[528]||=i(),c[529]||=a(`strong`,null,`Ross Geller:`,-1),c[530]||=i(` Crack isn’t even an intravenous drug!`,-1),c[531]||=a(`blockquote`,null,[a(`p`,null,`快克甚至不是静脉注射毒品！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/130.mp3`}),c[532]||=i(),c[533]||=a(`strong`,null,`Rachel Green:`,-1),c[534]||=i(` Well, you would know.`,-1),c[535]||=a(`blockquote`,null,[a(`p`,null,`嗯，你会知道的。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/131.mp3`}),c[536]||=i(),c[537]||=a(`strong`,null,`Judge:`,-1),c[538]||=i(` Now it also says here that you lied about your sexual preference before marriage?`,-1),c[539]||=a(`blockquote`,null,[a(`p`,null,`这里还说你在婚前的性取向上撒了谎？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/132.mp3`}),c[540]||=i(),c[541]||=a(`strong`,null,`Ross Geller:`,-1),c[542]||=i(` Oh, come on!`,-1),c[543]||=a(`blockquote`,null,[a(`p`,null,`哦，别这样！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/133.mp3`}),c[544]||=i(),c[545]||=a(`strong`,null,`Rachel Green:`,-1),c[546]||=i(` (starts to cry) Ross, please, I found the magazines!`,-1),c[547]||=a(`blockquote`,null,[a(`p`,null,`（开始哭）罗斯，拜托，我找到杂志了！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/134.mp3`}),c[548]||=i(),c[549]||=a(`strong`,null,`Judge:`,-1),c[550]||=i(` And finally that you were unable to consummate the marriage. Well, that makes sense since you’re gay and addicted to heroin.`,-1),c[551]||=a(`blockquote`,null,[a(`p`,null,`最后，你无法完成婚姻。嗯，这是有道理的，因为你是同性恋并且对海洛因上瘾。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/135.mp3`}),c[552]||=i(),c[553]||=a(`strong`,null,`Ross Geller:`,-1),c[554]||=i(` Okay, I’m sorry, this is insane! I-I-I’m not addicted to heroin, I’m not gay, and there is no problem with my ability to consummate anything! Look, I’ll consummate this marriage right here, right now!`,-1),c[555]||=a(`blockquote`,null,[a(`p`,null,`好吧，对不起，这太疯狂了！我，我，我没有海洛因上瘾，我不是同性恋，我完成任何事情的能力都没有问题！听着，我现在就在这里完成这段婚姻！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/136.mp3`}),c[556]||=i(),c[557]||=a(`strong`,null,`Judge:`,-1),c[558]||=i(` That won’t be necessary.`,-1),c[559]||=a(`blockquote`,null,[a(`p`,null,`那没有必要。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/137.mp3`}),c[560]||=i(),c[561]||=a(`strong`,null,`Ross Geller:`,-1),c[562]||=i(` And when we were dating we consummated like bunnies!`,-1),c[563]||=a(`blockquote`,null,[a(`p`,null,`当我们约会的时候，我们像兔子一样完美无缺！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/138.mp3`}),c[564]||=i(),c[565]||=a(`strong`,null,`Rachel Green:`,-1),c[566]||=i(` Ugh!`,-1),c[567]||=a(`blockquote`,null,[a(`p`,null,`啊！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/139.mp3`}),c[568]||=i(),c[569]||=a(`strong`,null,`Judge:`,-1),c[570]||=i(` Now if you were two involved in a serious relationship, that really creates a problem.`,-1),c[571]||=a(`blockquote`,null,[a(`p`,null,`现在，如果你们两个卷入了一段严肃的关系，那真的会产生问题。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/140.mp3`}),c[572]||=i(),c[573]||=a(`strong`,null,`Rachel Green:`,-1),c[574]||=i(` Ross! Your honor, rest assured relationship ended like two years ago! (To the stenographer) And could you strike "Consummated like bunnies" from the record?`,-1),c[575]||=a(`blockquote`,null,[a(`p`,null,`罗斯！法官大人，放心吧，我们的关系两年前就结束了！（对速记员）你能从记录中删掉“像兔子一样完美”吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/141.mp3`}),c[576]||=i(),c[577]||=a(`strong`,null,`Judge:`,-1),c[578]||=i(` Is there, anything in this record that is actually true?`,-1),c[579]||=a(`blockquote`,null,[a(`p`,null,`在这张记录里有什么是真实的吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/142.mp3`}),c[580]||=i(),c[581]||=a(`strong`,null,`Rachel Green:`,-1),c[582]||=i(` Well, yes, we got married in Vegas and uh, and the names I think.`,-1),c[583]||=a(`blockquote`,null,[a(`p`,null,`嗯，是的，我们在维加斯结婚了，嗯，还有我想的名字。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/143.mp3`}),c[584]||=i(),c[585]||=a(`strong`,null,`Judge:`,-1),c[586]||=i(` Well, based on what I heard, you two certainly don’t qualify for an annulment. If you two don’t want to be together you’ll have to file for divorce.`,-1),c[587]||=a(`blockquote`,null,[a(`p`,null,`嗯，根据我所听到的，你们两个当然没有资格被宣布无效。如果你们两个不想在一起，你就得申请离婚。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/144.mp3`}),c[588]||=i(),c[589]||=a(`strong`,null,`Ross Geller:`,-1),c[590]||=i(` (stands up) That’s great! Are you happy now? Look what you did with your funny, funny form!`,-1),c[591]||=a(`blockquote`,null,[a(`p`,null,`（站起来）太好了！你现在快乐吗？看看你用你那有趣的造型做了什么！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/145.mp3`}),c[592]||=i(),c[593]||=a(`strong`,null,`Rachel Green:`,-1),c[594]||=i(` (stands up as well) What?! Me?! What about you and your consummated like bunnies nonsense!`,-1),c[595]||=a(`blockquote`,null,[a(`p`,null,`（也站起来）什么？！我那你和你完美无缺的小兔子呢！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/146.mp3`}),c[596]||=i(),c[597]||=a(`strong`,null,`Ross Geller:`,-1),c[598]||=i(` And what—(notices the stenographer is still typing)—What are you typing that for? Did you hear what she said? We don’t get the annulment. Don’t type that! What?! Stop typing! (He goes over to where the stenographer is typing and in the process pushes Rachel out of his way.) Hey! Stop typing! (He’s still typing.) Stop typing! Stop typing!!`,-1),c[599]||=a(`blockquote`,null,[a(`p`,null,`还有什么？（注意到速记员还在打字）-你为什么要打字？你听到她说什么了吗？我们没有得到撤销权。别打那个！什么？！别打字了！（他走到速记员打字的地方，在打字过程中把瑞秋推开了。）嘿！别打字了！（他还在打字。）别打字！停止打字！！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/147.mp3`}),c[600]||=i(),c[601]||=a(`strong`,null,`Rachel Green:`,-1),c[602]||=i(` (to the judge) Okay, do you see, do you see what you’re keeping me married too?!`,-1),c[603]||=a(`blockquote`,null,[a(`p`,null,`（对法官）好吧，你看到了吗，你也看到了你让我结婚的原因吗？！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/148.mp3`}),c[604]||=i(),c[605]||=a(`strong`,null,`Judge:`,-1),c[606]||=i(` You need to get out of my chambers.`,-1),c[607]||=a(`blockquote`,null,[a(`p`,null,`你得离开我的房间。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/149.mp3`}),c[608]||=i(),c[609]||=a(`strong`,null,`Rachel Green:`,-1),c[610]||=i(` All right look lady here is the deal, I came here for an annulment and I am not leaving here until I get one!`,-1),c[611]||=a(`blockquote`,null,[a(`p`,null,`好吧，听着，女士，就这么定了，我来这里是为了解除婚约，在得到一份婚约之前我不会离开这里！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/150.mp3`}),c[612]||=i(),c[613]||=a(`strong`,null,`Ross Geller:`,-1),c[614]||=i(` Yeah!`,-1),c[615]||=a(`blockquote`,null,[a(`p`,null,`是啊！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/151.mp3`}),c[616]||=i(),c[617]||=a(`strong`,null,`Judge:`,-1),c[618]||=i(` Would you like to spend the night in jail?`,-1),c[619]||=a(`blockquote`,null,[a(`p`,null,`你愿意在监狱里过夜吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/152.mp3`}),c[620]||=t(` <strong>Rachel Green:</strong> And thank you for your time. (They both beat a hasty retreat.)<blockquote><p>谢谢你抽出时间。（他们两人仓促撤退。）</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Chandler is still doing the hairball thing as Monica and Phoebe are watching the babies. I can’t describe it, you’ll have to see it when it comes on in your area.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，当莫妮卡和菲比在看孩子的时候，钱德勒还在玩毛球游戏。我无法描述它，你必须在你的区域看到它。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S06/S06E05/153.mp3`}),c[621]||=i(),c[622]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[623]||=i(` (entering wearing nothing but Porsche clothes) So the Porsche guy took his car back.`,-1),c[624]||=a(`blockquote`,null,[a(`p`,null,`（进来时只穿着保时捷的衣服）所以那个保时捷的家伙把车开了回去。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/154.mp3`}),c[625]||=i(),c[626]||=a(`strong`,null,`Chandler Bing:`,-1),c[627]||=i(` But you found the keys to his clothes?`,-1),c[628]||=a(`blockquote`,null,[a(`p`,null,`但是你找到了他衣服的钥匙？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/155.mp3`}),c[629]||=i(),c[630]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[631]||=i(` No. No, I just uh, I just loved the way it feels when everybody thinks I own a Porsche.`,-1),c[632]||=a(`blockquote`,null,[a(`p`,null,`不，不，我只是，我只是喜欢大家都认为我拥有保时捷的那种感觉。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/156.mp3`}),c[633]||=i(),c[634]||=a(`strong`,null,`Monica Geller:`,-1),c[635]||=i(` And people will think you own a Porsche because you’re wearing the clothes?`,-1),c[636]||=a(`blockquote`,null,[a(`p`,null,`人们会认为你有一辆保时捷，因为你穿着那件衣服？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/157.mp3`}),c[637]||=i(),c[638]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[639]||=i(` Of course! Only an idiot would wear this stuff if you didn’t have the car! Right?`,-1),c[640]||=a(`blockquote`,null,[a(`p`,null,`当然！如果你没有车，只有傻瓜才会穿这个！对吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/158.mp3`}),c[641]||=i(),c[642]||=a(`strong`,null,`Chandler Bing:`,-1),c[643]||=i(` That is true.`,-1),c[644]||=a(`blockquote`,null,[a(`p`,null,`没错。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/159.mp3`}),c[645]||=i(),c[646]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[647]||=i(` Yeah, but only a genius would swallow a sonic blaster gun.`,-1),c[648]||=a(`blockquote`,null,[a(`p`,null,`是的，但只有天才才会吞下声爆枪。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/160.mp3`}),c[649]||=i(),c[650]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[651]||=i(` Oh, I’ve been there. Yeah, I am gonna go drive my Porsche. (Starts to leave.)`,-1),c[652]||=a(`blockquote`,null,[a(`p`,null,`哦，我去过那里。是的，我要去开我的保时捷。（开始离开。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/161.mp3`}),c[653]||=i(),c[654]||=a(`strong`,null,`Monica Geller:`,-1),c[655]||=i(` Joey, you know you don’t actually have one.`,-1),c[656]||=a(`blockquote`,null,[a(`p`,null,`乔伊，你知道你实际上没有。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/162.mp3`}),c[657]||=i(),c[658]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[659]||=i(` Come on! What are you doing?! I’m in character! Would you talk to her! (Storms out.)`,-1),c[660]||=a(`blockquote`,null,[a(`p`,null,`来吧！你在做什么？我很有个性！你能和她谈谈吗！（怒气冲冲地走了出去。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/163.mp3`}),c[661]||=i(),c[662]||=a(`strong`,null,`Chandler Bing:`,-1),c[663]||=i(` Ahh, I think it just moved. It’s really poking me.`,-1),c[664]||=a(`blockquote`,null,[a(`p`,null,`啊，我想它只是动了一下。它真的刺痛了我。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/164.mp3`}),c[665]||=i(),c[666]||=a(`strong`,null,`Monica Geller:`,-1),c[667]||=i(` All right, that’s it, we’re going to the emergency room.`,-1),c[668]||=a(`blockquote`,null,[a(`p`,null,`好了，就这样，我们去急诊室。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/165.mp3`}),c[669]||=i(),c[670]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[671]||=i(` What?! No, you can’t, you can’t leave me here with them! We’re baby-sitting!`,-1),c[672]||=a(`blockquote`,null,[a(`p`,null,`什么？！不，你不能，你不能把我留在这里和他们在一起！我们在照看孩子！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/166.mp3`}),c[673]||=i(),c[674]||=a(`strong`,null,`Monica Geller:`,-1),c[675]||=i(` The babies are asleep, I’m sure you’ll be okay on your own for a while!`,-1),c[676]||=a(`blockquote`,null,[a(`p`,null,`孩子们都睡着了，我相信你一个人会没事的！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/167.mp3`}),c[677]||=i(),c[678]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[679]||=i(` But you-you can’t leave me with them! We-we’re a team! We’re playing a zone! They’re gonna triple team me!`,-1),c[680]||=a(`blockquote`,null,[a(`p`,null,`但是你不能把我留给他们！我们是一个团队！我们在玩区域游戏！他们要把我三人组！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/168.mp3`}),c[681]||=i(),c[682]||=a(`strong`,null,`Monica Geller:`,-1),c[683]||=i(` He’s got something plastic lodged in his throat, we’ve got to go to the hospital.`,-1),c[684]||=a(`blockquote`,null,[a(`p`,null,`他喉咙里有东西卡了，我们得去医院。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/169.mp3`}),c[685]||=i(),c[686]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[687]||=i(` But no, because a doctor won’t be able to help him, it’s just gonna y’know naturally pass through his system in like seven years.`,-1),c[688]||=a(`blockquote`,null,[a(`p`,null,`但是不，因为医生不能帮助他，你知道，它会在七年内自然通过他的系统。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/170.mp3`}),c[689]||=i(),c[690]||=a(`strong`,null,`Chandler Bing:`,-1),c[691]||=i(` I think that’s gum.`,-1),c[692]||=a(`blockquote`,null,[a(`p`,null,`我想那是口香糖。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/171.mp3`}),c[693]||=i(),c[694]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[695]||=i(` I’m pretty sure it’s gun.`,-1),c[696]||=a(`blockquote`,null,[a(`p`,null,`我敢肯定是枪。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/172.mp3`}),c[697]||=i(),c[698]||=a(`strong`,null,`Chandler Bing:`,-1),c[699]||=i(` Okay, listen this really hurts. Let’s go.`,-1),c[700]||=a(`blockquote`,null,[a(`p`,null,`好吧，听着，这真的很痛。走吧。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/173.mp3`}),c[701]||=i(),c[702]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[703]||=i(` A real man wouldn’t just run to the hospital! (They don’t stop.) No! What would, what would Krog do? (They ignore her and Phoebe is left alone.)`,-1),c[704]||=a(`blockquote`,null,[a(`p`,null,`一个真正的男人不会跑去医院！（他们不停）不！克罗格会怎么做？（他们不理她，只剩下菲比一个人。）`)],-1),c[705]||=a(`hr`,null,null,-1),c[706]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The street, Joey is hanging out wearing his Porsche grab.`)],-1),c[707]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`在街上，乔伊穿着他的保时捷抓斗闲逛。`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/174.mp3`}),c[708]||=i(),c[709]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[710]||=i(` Why isn’t that valet back with my Porsche?`,-1),c[711]||=a(`blockquote`,null,[a(`p`,null,`为什么那个贴身男仆不带着我的保时捷回来？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/175.mp3`}),c[712]||=i(),c[713]||=a(`strong`,null,`Passerby:`,-1),c[714]||=i(` Maybe because you’ve got the keys?`,-1),c[715]||=a(`blockquote`,null,[a(`p`,null,`也许因为你有钥匙？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/176.mp3`}),c[716]||=i(),c[717]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[718]||=i(` (to women passing him) Porsche.`,-1),c[719]||=a(`blockquote`,null,[a(`p`,null,`（对经过他的女人）保时捷。`)],-1),c[720]||=a(`p`,null,[a(`em`,null,`(Ross and Rachel approach, they’re still yelling at each other.)`)],-1),c[721]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯和瑞秋走近，他们还在互相大喊大叫。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/177.mp3`}),c[722]||=i(),c[723]||=a(`strong`,null,`Rachel Green:`,-1),c[724]||=i(` This is totally your fault!`,-1),c[725]||=a(`blockquote`,null,[a(`p`,null,`这完全是你的错！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/178.mp3`}),c[726]||=i(),c[727]||=a(`strong`,null,`Ross Geller:`,-1),c[728]||=i(` My fault?! You threatened the judge!`,-1),c[729]||=a(`blockquote`,null,[a(`p`,null,`是我的错？！你威胁法官！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/179.mp3`}),c[730]||=i(),c[731]||=a(`strong`,null,`Rachel Green:`,-1),c[732]||=i(` Well, you ripped the paper out of the court reporter’s machine!!`,-1),c[733]||=a(`blockquote`,null,[a(`p`,null,`嗯，你从法庭记者的机器上撕下了报纸！！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/180.mp3`}),c[734]||=i(),c[735]||=a(`strong`,null,`Ross Geller:`,-1),c[736]||=i(` That was the only way I could get him to stop typing!`,-1),c[737]||=a(`blockquote`,null,[a(`p`,null,`那是我唯一能让他停止打字的方法！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/181.mp3`}),c[738]||=i(),c[739]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[740]||=i(` Hi! How are the Gellers?`,-1),c[741]||=a(`blockquote`,null,[a(`p`,null,`嗨！盖勒一家怎么样？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/182.mp3`}),c[742]||=i(),c[743]||=a(`strong`,null,`Rachel Green:`,-1),c[744]||=i(` Don’t call us that! (Storms away)`,-1),c[745]||=a(`blockquote`,null,[a(`p`,null,`别这么叫我们！（狂风暴雨）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/183.mp3`}),c[746]||=i(),c[747]||=a(`strong`,null,`Ross Geller:`,-1),c[748]||=i(` The judge wouldn’t let us get an annulment! Now we gotta get a divorce!! Did a Porsch throw up on you? (Walks on.)`,-1),c[749]||=a(`blockquote`,null,[a(`p`,null,`法官不会让我们被判无效的！现在我们得离婚了！！你身上吐了猪肉粥吗？（继续走。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/184.mp3`}),c[750]||=i(),c[751]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[752]||=i(` Hey! It’s Porsche!! (He’s right y’know.)`,-1),c[753]||=a(`blockquote`,null,[a(`p`,null,`嘿！是保时捷！！（你知道，他是对的。）`)],-1),c[754]||=a(`hr`,null,null,-1),c[755]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Phoebe is being triple teamed.`)],-1),c[756]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家，菲比被分成三组。`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/185.mp3`}),c[757]||=i(),c[758]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[759]||=i(` Me taking care of you is no problem, huh? You guys feel safe. Right? Okay, I’m gonna take that spit bubble as, "Yeah, I do!" Okay, after I get rid of this dirty diaper Leslie, I’ll set you up with a clean one. (She throws it at the garbage without looking, misses, and knocks over a vase and flowers, which fall to the floor and break.) Okay, I’m sorry. I didn’t mean to scare you. I just have to clean that up. Okay? ‘Cause let’s face it, we’re at Monica’s. (She crawls over, disposes of the diaper, picks up the flowers, and the vase.) I broke it. All right. Well, that’s just the way that goes. (She throws out both the flowers and the vase.) Okay, good. (She turns around and only counts two babies.) Why are there only two of you? Where is Leslie? Well, you can’t answer. (She starts looking for her) Leslie? Where are you Leslie? Leslie, now would be a good time for your first words! (She turns around and finds that Leslie has managed to crawl into the bottom drawer of the TV cabinet.) Well, look at you! Hey! You are a little bit mischievous! My gosh! (She picks her up and notices a surprise is waiting in the drawer.) Oh, you’re a lot mischievous! Well, it’ll dry. (Closes the drawer with her foot.) (To Leslie) Okay, you sit with your brother and sister now—who aren’t there! (They both have disappeared as well.)`,-1),c[760]||=a(`blockquote`,null,[a(`p`,null,`我照顾你没问题吧？你们感到安全。对吗？好吧，我会把那个吐出来的泡泡当成“是的，我喜欢！”好吧，等我把这脏尿布莱斯利脱掉后，我会给你准备一件干净的。（她没有看一眼就把它扔到了垃圾堆上，没打中，撞翻了花瓶和花，它们掉到了地上摔碎了。）好的，对不起。我不是故意吓唬你的。我得把它清理干净。好吗？”因为让我们面对现实，我们在莫妮卡家。（她爬了过来，扔掉了尿布，捡起了花和花瓶。）我把它打碎了。好吧嗯，就是这样。（她把花和花瓶都扔掉了。）好的，很好。（她转过身来，只数了两个婴儿。）为什么你们只有两个？莱斯利在哪里？嗯，你不能回答。（她开始找她）莱斯利？莱斯利，你在哪里？莱斯利，现在正是你说第一句话的好时机！（她转过身，发现莱斯利设法爬进了电视柜的底部抽屉。）好吧，看看你！嘿你有点淘气！天哪！（她把她抱起来，发现抽屉里有一个惊喜等着她。）哦，你真淘气！好吧，它会干的。（用她的脚关上抽屉。）（对莱斯利）好吧，你现在和你的兄弟姐妹坐在一起，他们不在那里！（他们也都失踪了。）`)],-1),c[761]||=a(`p`,null,[i(`⏱ `),a(`em`,null,`Time Lapse, the babies are finally asleep. Good for Phoebe! The only problem is, Monica’s apartment looks like a tornado, a hurricane, a swarm of locusts, fire, brimstone, hail, and giant man-eating, radioactive ants have torn the place apart. Needless to say, it’s messy enough to cause Monica to die of shock right away. Parents with small children know what I’m talking about.`)],-1),c[762]||=a(`blockquote`,null,[a(`p`,null,`[久而久之，孩子们终于睡着了。这对菲比来说很好！唯一的问题是，莫妮卡的公寓看起来像龙卷风、飓风、蝗虫、大火、硫磺、冰雹，还有巨大的食人动物，放射性蚂蚁把这个地方撕成了碎片。不用说，这里的混乱足以让莫妮卡马上死于休克。有小孩的父母你知道我在说什么`)],-1),r(p,{src:`/audio/friends/S06/S06E05/186.mp3`}),c[763]||=i(),c[764]||=a(`strong`,null,`Chandler Bing:`,-1),c[765]||=i(` (entering) Hey!`,-1),c[766]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/187.mp3`}),c[767]||=i(),c[768]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[769]||=i(` (exhausted) How do you feel?`,-1),c[770]||=a(`blockquote`,null,[a(`p`,null,`（筋疲力尽）你感觉怎么样？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/188.mp3`}),c[771]||=i(),c[772]||=a(`strong`,null,`Chandler Bing:`,-1),c[773]||=i(` Well, let’s just say that Krog will be fully equipped to destroy the universe again in twelve to fourteen hours.`,-1),c[774]||=a(`blockquote`,null,[a(`p`,null,`好吧，我们就说克罗格将在12到14小时内完全装备好再次摧毁宇宙。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/189.mp3`}),c[775]||=i(),c[776]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[777]||=i(` Okay, so I totally took care of the babies all by myself! I fed ‘em, bathed ‘em, and put ‘em to bed.`,-1),c[778]||=a(`blockquote`,null,[a(`p`,null,`好吧，所以我完全是一个人照顾孩子的！我喂他们，给他们洗澡，然后让他们上床睡觉。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/190.mp3`}),c[779]||=i(),c[780]||=a(`strong`,null,`Chandler Bing:`,-1),c[781]||=i(` And protected them from a tornado?`,-1),c[782]||=a(`blockquote`,null,[a(`p`,null,`保护他们免受龙卷风的袭击？`)],-1),c[783]||=a(`p`,null,[a(`em`,null,`(Monica enters and her jaw drops in horror.)`)],-1),c[784]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡走进来，吓得下巴都掉了下来。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/191.mp3`}),c[785]||=i(),c[786]||=a(`strong`,null,`Monica Geller:`,-1),c[787]||=i(` Oh my God.`,-1),c[788]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/192.mp3`}),c[789]||=i(),c[790]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[791]||=i(` I know, the babies are asleep.`,-1),c[792]||=a(`blockquote`,null,[a(`p`,null,`我知道，孩子们都睡着了。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/193.mp3`}),c[793]||=i(),c[794]||=a(`strong`,null,`Monica Geller:`,-1),c[795]||=i(` Phoebe, what, what happened here?!`,-1),c[796]||=a(`blockquote`,null,[a(`p`,null,`菲比，这里发生了什么？！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/194.mp3`}),c[797]||=i(),c[798]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[799]||=i(` I did it! I took care of the babies all by myself!`,-1),c[800]||=a(`blockquote`,null,[a(`p`,null,`我做到了！我一个人照顾孩子们！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/195.mp3`}),c[801]||=i(),c[802]||=a(`strong`,null,`Monica Geller:`,-1),c[803]||=i(` But my apartment!`,-1),c[804]||=a(`blockquote`,null,[a(`p`,null,`但是我的公寓！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/196.mp3`}),c[805]||=i(),c[806]||=a(`strong`,null,`Chandler Bing:`,-1),c[807]||=i(` Was the setting of Phoebe’s triumph.`,-1),c[808]||=a(`blockquote`,null,[a(`p`,null,`是菲比获胜的背景。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/197.mp3`}),c[809]||=i(),c[810]||=a(`strong`,null,`Monica Geller:`,-1),c[811]||=i(` But the mess!`,-1),c[812]||=a(`blockquote`,null,[a(`p`,null,`但是一团糟！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/198.mp3`}),c[813]||=i(),c[814]||=a(`strong`,null,`Chandler Bing:`,-1),c[815]||=i(` Is not as important as the fact that Phoebe took care of the babies all by herself.`,-1),c[816]||=a(`blockquote`,null,[a(`p`,null,`没有菲比独自照顾孩子那么重要。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/199.mp3`}),c[817]||=i(),c[818]||=a(`strong`,null,`Monica Geller:`,-1),c[819]||=i(` You’re right, you’re right I shouldn’t freak out. ‘Cause this is what will happen when you and I have babies! When will that be?!`,-1),c[820]||=a(`blockquote`,null,[a(`p`,null,`你说得对，你说得对，我不应该发疯因为这就是当你和我有孩子的时候会发生的事情！那什么时候？！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/200.mp3`}),c[821]||=i(),c[822]||=a(`strong`,null,`Chandler Bing:`,-1),c[823]||=i(` (pause) Phoebe, would you take a look at this mess!!!!`,-1),c[824]||=a(`blockquote`,null,[a(`p`,null,`（停顿）菲比，你能看看这一团糟吗！！！！`)],-1),c[825]||=a(`hr`,null,null,-1),c[826]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Ross’s apartment, Rachel is packing what she still has over there as Ross enters.`)],-1),c[827]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`罗斯的公寓，当罗斯进来时，瑞秋正在收拾她还在那里的东西。`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/201.mp3`}),c[828]||=i(),c[829]||=a(`strong`,null,`Rachel Green:`,-1),c[830]||=i(` (deadpan) Oh honey thank God you’re home, I was getting worried.`,-1),c[831]||=a(`blockquote`,null,[a(`p`,null,`（面无表情）哦，亲爱的，感谢上帝你回来了，我开始担心了。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/202.mp3`}),c[832]||=i(),c[833]||=a(`strong`,null,`Ross Geller:`,-1),c[834]||=i(` I picked up the divorce papers. Uh, I’ve already signed everything and I put little ‘X’s where you need to sign.`,-1),c[835]||=a(`blockquote`,null,[a(`p`,null,`我拿了离婚文件。呃，我已经签了所有的东西，我把小X放在你需要签的地方。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/203.mp3`}),c[836]||=i(),c[837]||=a(`strong`,null,`Rachel Green:`,-1),c[838]||=i(` Oh, little ‘X’s! Great! That makes up for everything!`,-1),c[839]||=a(`blockquote`,null,[a(`p`,null,`哦，小X！伟大的这弥补了一切！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/204.mp3`}),c[840]||=i(),c[841]||=a(`strong`,null,`Ross Geller:`,-1),c[842]||=i(` Y’know, I-I—you’ve done a lot of stupid stuff too! Okay?`,-1),c[843]||=a(`blockquote`,null,[a(`p`,null,`你知道，我-我-你也做了很多蠢事！可以`)],-1),r(p,{src:`/audio/friends/S06/S06E05/205.mp3`}),c[844]||=i(),c[845]||=a(`strong`,null,`Rachel Green:`,-1),c[846]||=i(` Oh, name one stupid thing that is as stupid as this one!`,-1),c[847]||=a(`blockquote`,null,[a(`p`,null,`哦，说出一件和这件一样愚蠢的事！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/206.mp3`}),c[848]||=i(),c[849]||=a(`strong`,null,`Ross Geller:`,-1),c[850]||=i(` Okay, how about you flew to London to stop my wedding! Ah, how about you told me you loved me after I was already married!`,-1),c[851]||=a(`blockquote`,null,[a(`p`,null,`好吧，你飞去伦敦阻止我的婚礼怎么样！啊，不如在我结婚后告诉我你爱我吧！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/207.mp3`}),c[852]||=i(),c[853]||=a(`strong`,null,`Rachel Green:`,-1),c[854]||=i(` Hey! Wait a minute! That was different! I did those things because I was in love with you!`,-1),c[855]||=a(`blockquote`,null,[a(`p`,null,`嘿！等一下！那不一样！我做那些事是因为我爱上了你！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/208.mp3`}),c[856]||=i(),c[857]||=a(`strong`,null,`Ross Geller:`,-1),c[858]||=i(` Yeah! Right!`,-1),c[859]||=a(`blockquote`,null,[a(`p`,null,`是啊！正确的！`)],-1),c[860]||=a(`p`,null,[a(`em`,null,`(Pause.)`)],-1),c[861]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（停顿。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/209.mp3`}),c[862]||=i(),c[863]||=a(`strong`,null,`Ross Geller:`,-1),c[864]||=i(` You’re right. That’s very different. So let’s, let’s just sign the papers. All right? (Sits down and Rachel keeps standing there.) What?`,-1),c[865]||=a(`blockquote`,null,[a(`p`,null,`你说得对。那很不一样。那么，让我们，让我们在文件上签字。好吧（坐下来，瑞秋一直站在那里。）什么？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/210.mp3`}),c[866]||=i(),c[867]||=a(`strong`,null,`Rachel Green:`,-1),c[868]||=i(` Nothing. (Sits down.)`,-1),c[869]||=a(`blockquote`,null,[a(`p`,null,`没什么。（坐下。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/211.mp3`}),c[870]||=i(),c[871]||=a(`strong`,null,`Ross Geller:`,-1),c[872]||=i(` Okay, can we just sign please?`,-1),c[873]||=a(`blockquote`,null,[a(`p`,null,`好的，我们可以签个名吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/212.mp3`}),c[874]||=i(),c[875]||=a(`strong`,null,`Rachel Green:`,-1),c[876]||=i(` Uh-hmm. (Just as Rachel finishes signing her name, Ross yanks each page out of the way.)`,-1),c[877]||=a(`blockquote`,null,[a(`p`,null,`嗯。（瑞秋刚签完名，罗斯就把每一页都扯到一边。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/213.mp3`}),c[878]||=i(),c[879]||=a(`strong`,null,`Ross Geller:`,-1),c[880]||=i(` Congratulations. (Gets up to leave.)`,-1),c[881]||=a(`blockquote`,null,[a(`p`,null,`祝贺你。（起身离开。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/214.mp3`}),c[882]||=i(),c[883]||=a(`strong`,null,`Rachel Green:`,-1),c[884]||=i(` Okay Ross, we’re—wait a minute. Umm, I uh, I kinda have a little confession.`,-1),c[885]||=a(`blockquote`,null,[a(`p`,null,`好的，罗斯，我们等一下。呃，我呃，我有点坦白。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/215.mp3`}),c[886]||=i(),c[887]||=a(`strong`,null,`Ross Geller:`,-1),c[888]||=i(` What?`,-1),c[889]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/216.mp3`}),c[890]||=i(),c[891]||=a(`strong`,null,`Rachel Green:`,-1),c[892]||=i(` Well, y’know this whole marriage thing, kinda my idea.`,-1),c[893]||=a(`blockquote`,null,[a(`p`,null,`嗯，你知道整个婚姻的事情，有点像我的想法。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/217.mp3`}),c[894]||=i(),c[895]||=a(`strong`,null,`Ross Geller:`,-1),c[896]||=i(` Excuse me?`,-1),c[897]||=a(`blockquote`,null,[a(`p`,null,`劳驾？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/218.mp3`}),c[898]||=i(),c[899]||=a(`strong`,null,`Rachel Green:`,-1),c[900]||=i(` Well, remember how we were too drunk to remember anything the night we were married?`,-1),c[901]||=a(`blockquote`,null,[a(`p`,null,`还记得我们结婚那天晚上喝醉得什么都不记得吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/219.mp3`}),c[902]||=i(),c[903]||=a(`strong`,null,`Ross Geller:`,-1),c[904]||=i(` Yeah?`,-1),c[905]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/220.mp3`}),c[906]||=i(),c[907]||=a(`strong`,null,`Rachel Green:`,-1),c[908]||=i(` And uh, yeah, I didn’t really, I didn’t want to say anything, but it kinda it just, it kinda kept coming back to me, and umm, remember we were in the casino and for some reason thought it would be funny to eat a lot of grapes. And uh, and I thought it would be funnier if we got married. So as a, as a compromise we decided first to get married, and then (Ross joins in) to eat a lot of grapes. So umm, sorry I got us into this mess.`,-1),c[909]||=a(`blockquote`,null,[a(`p`,null,`嗯，是的，我没有真的，我什么都不想说，但我一直在想，嗯，记得我们在赌场，不知为什么觉得吃很多葡萄会很有趣。我觉得如果我们结婚会更有趣。所以作为一种妥协，我们决定先结婚，然后（罗斯加入）吃很多葡萄。对不起，我把我们弄得一团糟。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/221.mp3`}),c[910]||=i(),c[911]||=a(`strong`,null,`Ross Geller:`,-1),c[912]||=i(` So then if-if—I mean if you think about it, this is all (Pause.) your fault.`,-1),c[913]||=a(`blockquote`,null,[a(`p`,null,`那么如果，如果，我是说，如果你仔细想想，这都是你的错。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/222.mp3`}),c[914]||=i(),c[915]||=a(`strong`,null,`Rachel Green:`,-1),c[916]||=i(` Yeah, don’t push it though.`,-1),c[917]||=a(`blockquote`,null,[a(`p`,null,`是啊，不过别推。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/223.mp3`}),c[918]||=i(),c[919]||=a(`strong`,null,`Ross Geller:`,-1),c[920]||=i(` I’ve got to say; I know I divorce a lot of women, never thought I would be divorcing you.`,-1),c[921]||=a(`blockquote`,null,[a(`p`,null,`我得说；我知道我和很多女人离婚，从没想过我会和你离婚。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/224.mp3`}),c[922]||=i(),c[923]||=a(`strong`,null,`Rachel Green:`,-1),c[924]||=i(` I know. I always thought if you and I got married, it would be the one that stuck. And it wouldn’t be a secret, and we wouldn’t have our wedding dinner at Pizza Hut. (They both laugh.)`,-1),c[925]||=a(`blockquote`,null,[a(`p`,null,`我知道。我一直在想，如果你和我结婚的话，那一定会是我们相爱的那个人。这不是秘密，我们也不会在必胜客吃我们的婚礼晚餐。（他们都笑了。）`)],-1),r(p,{src:`/audio/friends/S06/S06E05/225.mp3`}),c[926]||=i(),c[927]||=a(`strong`,null,`Ross Geller:`,-1),c[928]||=i(` Did I, did I even treat?`,-1),c[929]||=a(`blockquote`,null,[a(`p`,null,`我，我有请过客吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/226.mp3`}),c[930]||=i(),c[931]||=a(`strong`,null,`Rachel Green:`,-1),c[932]||=i(` No, it was on the house, it was, it was a newlywed special.`,-1),c[933]||=a(`blockquote`,null,[a(`p`,null,`不，是在房子上，是的，是新婚特别节目。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/227.mp3`}),c[934]||=i(),c[935]||=a(`strong`,null,`Ross Geller:`,-1),c[936]||=i(` That may be the most depressing thing I’ve heard in my life. I should probably get these to my lawyer’s office.`,-1),c[937]||=a(`blockquote`,null,[a(`p`,null,`这可能是我一生中听到的最令人沮丧的事情了。我应该把这些送到我律师的办公室。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/228.mp3`}),c[938]||=i(),c[939]||=a(`strong`,null,`Rachel Green:`,-1),c[940]||=i(` Hey, thanks Ross, for taking care of all of this.`,-1),c[941]||=a(`blockquote`,null,[a(`p`,null,`嘿，谢谢罗斯，谢谢你照顾这一切。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/229.mp3`}),c[942]||=i(),c[943]||=a(`strong`,null,`Ross Geller:`,-1),c[944]||=i(` Eh, no problem.`,-1),c[945]||=a(`blockquote`,null,[a(`p`,null,`嗯，没问题。`)],-1),c[946]||=a(`p`,null,[a(`em`,null,`(They hug.)`)],-1),c[947]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们拥抱。）`)])],-1),r(p,{src:`/audio/friends/S06/S06E05/230.mp3`}),c[948]||=i(),c[949]||=a(`strong`,null,`Rachel Green:`,-1),c[950]||=i(` I’m gonna need a copy of those.`,-1),c[951]||=a(`blockquote`,null,[a(`p`,null,`我需要一份。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/231.mp3`}),c[952]||=t(` <strong>Ross Geller:</strong> Totally. (Exits.)<blockquote><p>完全正确。（退出。）</p></blockquote><p>Ending Credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>The street, Joey is messing with a car cover and still wearing the Porsche stuff. This guy playing street football catches a pass next to the car cover Joey is fooling around with.</em></p><blockquote><p>🎬 <em>在街上，乔伊摆弄着汽车罩，还穿着保时捷的衣服。一个玩街头足球的家伙在乔伊玩弄的汽车罩旁边接住了一张通行证。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S06/S06E05/232.mp3`}),c[953]||=i(),c[954]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[955]||=i(` Hey! Hey! Be careful around my Porsche!`,-1),c[956]||=a(`blockquote`,null,[a(`p`,null,`嘿！嘿小心我的保时捷！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/233.mp3`}),c[957]||=i(),c[958]||=a(`strong`,null,`Woman:`,-1),c[959]||=i(` (the same one from before approaches) Hi Joey.`,-1),c[960]||=a(`blockquote`,null,[a(`p`,null,`（和以前一样）嗨，乔伊。`)],-1),r(p,{src:`/audio/friends/S06/S06E05/234.mp3`}),c[961]||=i(),c[962]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[963]||=i(` Hey! How you doin’?`,-1),c[964]||=a(`blockquote`,null,[a(`p`,null,`嘿！你好吗？`)],-1),r(p,{src:`/audio/friends/S06/S06E05/235.mp3`}),c[965]||=i(),c[966]||=a(`strong`,null,`Woman:`,-1),c[967]||=i(` (to her friend) He has the most amazing Porsche under there!`,-1),c[968]||=a(`blockquote`,null,[a(`p`,null,`（对她的朋友）他有最棒的保时捷！`)],-1),r(p,{src:`/audio/friends/S06/S06E05/236.mp3`}),c[969]||=i(),c[970]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[971]||=i(` I’d love to show ya, but I just tucked her in. She’s sleeping. (The women both laugh) Hey uh, would you two girls like to go for a drink? (Just then the same guy with the football dives to make a catch, lands on the car cover, and collapses it. It turns out that Joey set up a bunch of boxes to make it look like a Porsche.)`,-1),c[972]||=a(`blockquote`,null,[a(`p`,null,`我很想让你看看，但我只是把她塞进去了。她在睡觉。（两个女人都笑了）嘿，呃，你们两个女孩想去喝一杯吗？（就在这时，同一个足球运动员跳水接球，降落在汽车的盖子上，然后把它撞倒。结果乔伊装了一堆盒子，让它看起来像一辆保时捷。）`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};